import {clone,personas,families,diff,fieldName,setPath,commandsFrom,parsePhone,validate} from './shared.mjs';
const concepts={
  dispatch:{name:'Dispatch',tag:'A clear desk. A shorter day.',thesis:'A compact record workspace that keeps daily edits close and evidence one step away.',number:'01'},
  ledger:{name:'Ledger',tag:'Every change has a place.',thesis:'A reading desk organized around the record of change. Compare, inspect and edit in context.',number:'02'},
  relay:{name:'Relay',tag:'One task. Fully resolved.',thesis:'A focused sequence of small tasks, with a review sheet and an assistant at the point of action.',number:'03'}
};
const variant=location.pathname.split('/')[1];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>x===null||x===undefined?'Not set':typeof x==='boolean'?(x?'Yes':'No'):String(x);
const time=t=>new Intl.DateTimeFormat('en-GB',{timeZone:'America/Mexico_City',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(t));
const btn=(text,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const chip=(x,cls='')=>`<span class="chip ${cls}">${esc(x)}</span>`;
let theme=localStorage.getItem('overmind-a-theme-'+variant)||'light';document.documentElement.dataset.theme=theme;
let state,contact='lina',view='contact',historyMode='diff',revision=7,compare=6,selectedUnit=null,step=0;
let persona=sessionStorage.getItem('overmind-a-persona-'+variant)||'Mariana';
let draft=null,base=null,draftEpoch=null,conflict=null,choices={},uncertain=false,proposal=false,proposalBackup=null;
let sidekick=false,assistantMessage='',highlight='',notice='',error='',demo=false,simulation='',busy=false,transitioning=false;
let filters={search:'',actor:'',contact:'',family:'',range:'all'}, peers=[];
const tabId=crypto.randomUUID();
let backToActivity=false,focusReturn='assistant';
const cap=()=>personas[persona], record=()=>state.contacts[contact], latest=()=>record().revisions.at(-1), snapshot=()=>draft||latest().snapshot;
const endpoint=op=>`/demo/${variant}/${op}?persona=${encodeURIComponent(persona)}`;
async function api(op,data) {const r=await fetch(endpoint(op),data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});return {...await r.json(),httpStatus:r.status};}
async function refresh(renderNow=true) {state=await api('state');peers=state.presence||[];if(renderNow) render();}
async function presence() {if(!state)return;await api('presence',{tab:tabId,contact,section:draft?'Editing channels':view==='history'?'History':view==='activity'?'Activity':'Contact'});}
function revisions() {return record().revisions;}
function rev(n) {return revisions().find(x=>x.revision===Number(n))||latest();}
function startDraft(){if(!cap().edit){error='You have read access. Editing requires a contact Edit grant.';return false;}if(!draft){base=clone(latest().snapshot);draft=clone(base);draftEpoch=state.epoch;draft.revision=latest().revision;}return true;}
function clearDraft(){draft=null;base=null;conflict=null;choices={};uncertain=false;proposal=false;proposalBackup=null;error='';}
function changes(){return draft?diff(base,draft):[];}
function openHistory(n=latest().revision,fromActivity=false){revision=Number(n);compare=Math.max(1,revision-1);view='history';historyMode='diff';backToActivity=fromActivity;simulation='';}
function filteredUnits(){
  if(!cap().activity) return [];
  return state.units.filter(u=> (!filters.actor||u.actor===filters.actor)&&(!filters.contact||u.contact===filters.contact)&&(!filters.family||u.actions.some(a=>a.kind.startsWith(filters.family+'.')))&&(!filters.search||JSON.stringify([u.title,u.actor,state.contacts[u.contact].revisions.at(-1).snapshot.profile.name,u.actions.map(a=>a.kind)]).toLowerCase().includes(filters.search.toLowerCase()))&&(filters.range==='all'||(filters.range==='week'?u.time>='2026-09-01'&&u.time<'2026-09-09':u.time>='2026-09-07'))).sort((a,b)=>b.time.localeCompare(a.time));
}
function nav(){return `<nav class="area-nav" aria-label="Workspace areas">${[['contact',variant==='ledger'?'Live record':variant==='relay'?'Work queue':'Contact'],['history',variant==='ledger'?'Evidence desk':variant==='relay'?'Review trail':'History'],['activity',variant==='relay'?'Tenant feed':'Tenant activity']].map(([v,t])=>btn(t,'view','nav-item '+(view===v?'active':''),`data-view="${v}" aria-current="${view===v?'page':'false'}"`)).join('')}</nav>`;}
function identity(){return `<div class="tenant-mark"><span class="brand-symbol">o<span>·</span></span><div><strong>overmind</strong><small>Vértice Demo</small></div></div>`;}
function toolbar(){return `<div class="tools">${btn(theme==='light'?'◐ Dark':'☀ Light','theme','quiet',`aria-label="Switch to ${theme==='light'?'dark':'light'} mode"`)}${btn(variant==='relay'?'⌘ Guide':'✦ Sidekick','assistant','assistant-trigger',`aria-expanded="${sidekick}" id="assistant"`)}${btn('Demo','demo','quiet',`aria-expanded="${demo}"`)}<a class="gallery-link" href="/" aria-label="Open concept gallery">↗</a></div>`;}
function personSwitch(){return `<label class="persona"><span class="avatar small">${esc(persona[0])}</span><select aria-label="Demo persona" id="persona">${Object.entries(personas).map(([n,p])=>`<option value="${n}" ${persona===n?'selected':''}>${n} · ${p.role}</option>`).join('')}</select></label>`;}
function contactSwitch(){return `<div class="record-switch">${Object.values(state.contacts).map(c=>btn(`<span class="avatar ${c.id==='norte'?'org':''}">${c.id==='lina'?'LT':'NT'}</span><span><strong>${c.id==='lina'?'Lina Torres':'Norte Taller'}</strong><small>${c.category}</small></span>`,'contact',c.id===contact?'selected':'',`data-contact="${c.id}"`)).join('')}</div>`;}
function presenceUI(){const others=peers.filter(x=>x.tab!==tabId&&x.contact===contact);return `<div class="presence"><span class="presence-dot"></span>${others.length?others.map(x=>`${esc(x.persona)} · ${esc(x.section)}`).join(' / '):'Only you in this record'}<span class="muted"> · Awareness, no lock</span></div>`;}
function head(kicker,title,description=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1>${description?`<p class="description">${description}</p>`:''}</div><span class="edition">${concepts[variant].number} / ${concepts[variant].name}</span></div>`;}
function banner(){return `${notice?`<div class="notice" role="status"><span>${esc(notice)}</span>${btn('View evidence →','saved-history','text-button')}${btn('×','dismiss-notice','icon-button','aria-label="Dismiss saved message"')}</div>`:''}${error?`<div class="error" role="alert">${esc(error)}</div>`:''}${uncertain?`<div class="warning" role="alert"><strong>Save outcome unknown</strong><p>The response was lost. Your changes may have committed. Your draft is kept here. Do not resubmit.</p>${btn('Investigate latest state','investigate','primary')}${btn('Discard local draft','cancel','quiet')}</div>`:''}${conflict?conflictUI():''}`;}
function demoUI(){return !demo?'':`<section class="demo-panel" aria-label="Prototype demo controls"><div><strong>Local prototype controls</strong><small>Simulated assistant, permissions, search, activity & presence. No external model. No live backend.</small></div><div class="demo-actions">${btn('Reset story','reset','quiet',cap().edit?'':'disabled')}${btn('Start conflict at revision 3','scenario','quiet',cap().edit?'':'disabled')}${btn("Simulate Bruno’s update",'bruno','quiet',cap().edit?'':'disabled')}<label>Review a state <select id="simulation"><option value="">Normal</option>${[['loading','Loading'],['empty','Empty activity'],['denied','Permission denied'],['unavailable','History unavailable'],['uncertain','Next Save: uncertain outcome']].map(([v,n])=>`<option value="${v}" ${simulation===v?'selected':''}>${n}</option>`).join('')}</select></label></div><p>Conflict setup resets only ${concepts[variant].name}. Open the same route in a second tab as Bruno. Each tab keeps its own draft and persona.</p></section>`;}
function statusView(){if(simulation==='loading')return `<div class="state-card" aria-busy="true"><span class="loading-line"></span><h2>Loading the contact workspace</h2><p>Retrieving a coherent contact revision…</p>${btn('Finish loading','normal','primary')}</div>`;if(simulation==='denied')return `<div class="state-card"><span class="big-glyph">⊘</span><h2>Access isn’t available</h2><p>Your current grant does not allow this view. Contact your administrator.</p>${btn('Return to permitted view','normal','primary')}</div>`;return null;}
function render(){
  if(!state)return;
  const active=document.activeElement?.id;const sel=document.activeElement?.selectionStart;const selEnd=document.activeElement?.selectionEnd;
  document.body.dataset.variant=variant;
  const content=statusView()||(view==='contact'?contactUI():view==='history'?historyUI():activityUI());
  const shell=variant==='dispatch'?`<aside class="rail">${identity()}<p class="rail-label">WORKSPACE</p>${nav()}<div class="rail-bottom"><span class="tenant-badge">V</span><strong>Vértice Demo</strong><small>Contact operations</small><a href="/">← All explorations</a></div></aside><div class="shell"><header class="topbar"><span class="breadcrumbs">Workspace <span>/</span> ${view==='contact'?'Contacts':view==='history'?'Contact history':'Tenant activity'}</span>${toolbar()}</header><div class="workspace">${contactSwitch()}<main id="main" tabindex="-1">${demoUI()}${banner()}${content}</main></div></div>`:variant==='ledger'?`<header class="ledger-header">${identity()}${nav()}${toolbar()}</header><div class="ledger-subbar"><span>THE RECORD OF CHANGE</span>${personSwitch()}</div><main id="main" tabindex="-1" class="ledger-main">${demoUI()}${banner()}${content}</main>`:`<header class="relay-header">${identity()}<span class="relay-title">${concepts[variant].name} / Contact operations</span>${toolbar()}</header><div class="relay-frame"><aside class="relay-nav">${nav()}${contactSwitch()}<div class="relay-note"><span>↳</span><p>A small change.<br>A complete record.</p></div></aside><main id="main" tabindex="-1">${demoUI()}${banner()}${content}</main></div>`;
  $('#app').innerHTML=shell+(sidekick?assistantUI():'')+`<footer class="app-footer"><span>LOCAL EXPLORATION · AGENT A</span><span>America/Mexico_City · UTC−06</span>${variant!=='ledger'?personSwitch():`<span>Fictional data · ${cap().role}</span>`}</footer>`;
  bind();
  if(active&&$('#'+CSS.escape(active))){const el=$('#'+CSS.escape(active));el.focus({preventScroll:true});if(typeof sel==='number'&&el.setSelectionRange&&['text','search','tel','url','textarea'].includes(el.type))el.setSelectionRange(sel,selEnd);}
}
function recordTitle(){return `<div class="record-title"><span class="avatar large ${contact==='norte'?'org':''}">${contact==='lina'?'LT':'NT'}</span><div><div class="inline">${chip(record().category)}${chip('Revision '+latest().revision,'soft')}${cap().directory?chip('Public directory only'):''}</div><h1>${esc(latest().snapshot.profile.name)}</h1><p>${contact==='lina'?'A person, with the details that keep work moving.':'An independent organization. No recorded employment relationship.'}</p></div></div>`;}
function contactUI(){
  if(variant==='relay')return relayContact();
  const s=snapshot();
  const formBody=draft?editForm():readCard(s);
  const main=`<section class="record-paper">${formBody}</section>`;
  if(variant==='ledger')return `${head('LIVE RECORD / '+record().category.toUpperCase(),esc(s.profile.name),'Read the present. Keep the path to its evidence.')}<div class="ledger-record-toolbar">${contactSwitch()}${btn(draft?'Editing record':'Edit this record','edit','primary',!cap().edit||draft?'disabled':'')}${btn('Open evidence desk ↗','saved-history','quiet')}</div>${presenceUI()}<div class="ledger-live">${main}<aside class="margin-notes"><span class="folio">${String(latest().revision).padStart(2,'0')}</span><h3>Current revision</h3><p>${esc(latest().title||'Public live channels')}</p>${latest().actor?`<small>Changed by ${latest().actor}<br>${time(latest().time)} · UTC−06</small>`:''}<hr><h3>Saved order matters</h3><p>The first saved channel is primary. Moving it preserves its identity.</p><hr><h3>In context</h3><p>Mailing addresses are independent of phone numbering regions.</p>${btn('Ask about this record','assistant','text-button')}</aside></div>${draft?savebar():''}`;
  return `<div class="contact-top">${recordTitle()}<div>${btn('View history ↗','saved-history','quiet')}${btn('Edit contact','edit','primary',!cap().edit||draft?'disabled':'')}</div></div>${presenceUI()}<div class="dispatch-record">${main}<aside class="context-column"><h2>At a glance</h2><dl><dt>Workspace</dt><dd>Vértice Demo</dd><dt>Access</dt><dd>${esc(cap().role)}</dd><dt>Current revision</dt><dd>${latest().revision} ${latest().actor?'· '+latest().actor:''}</dd></dl><div class="context-rule"></div><h2>Recent changes</h2>${cap().history?revisions().slice(-3).reverse().map(r=>btn(`<span class="tiny-date">${time(r.time)}</span><strong>${esc(r.title)}</strong><span>Revision ${r.revision} · ${r.actor} ↗</span>`,'revision','recent-change',`data-revision="${r.revision}"`)).join(''):'<p>History requires a separate grant.</p>'}<div class="sidekick-nudge"><span>✦</span><h3>The context is already here.</h3><p>Ask what changed, or stage a small edit.</p>${btn('Open sidekick →','assistant','text-button')}</div></aside></div>${draft?savebar():''}`;
}
function readCard(s){return `<div class="section-heading"><h2>Contact details</h2><span class="muted">${cap().directory?'Public channels':'Internal workspace'}</span></div>${families.map(f=>`<section class="channel-section"><div class="section-heading"><h3>${f==='email'?'Email addresses':f==='phone'?'Phone numbers':'Mailing address'}</h3>${cap().edit?btn('+ Add '+f,'add','text-button',`data-family="${f}" ${f==='address'?'disabled title="This bounded prototype supports one address association"':''}`):''}</div>${s[f].filter(c=>!c.deleted).sort((a,b)=>a.order-b.order).map(c=>`<div class="channel-row"><span class="channel-icon" aria-hidden="true">${f==='email'?'@':f==='phone'?'⌕':'⌂'}</span><div class="channel-value"><strong>${esc(c.value).replace(/\n/g,'<br>')}</strong><div class="channel-meta"><span>${esc(c.label)}</span>${c.extension?`<span>Extension ${esc(c.extension)}</span>`:''}${c.order===1?chip('Primary','primary-chip'):chip('Position '+c.order)}${chip(c.public?'Public':'Private',c.public?'':'private')}</div></div>${cap().edit?btn('Edit','edit','row-edit',`data-field="${f}-${c.ordinal}-value" aria-label="Edit ${f} ${c.ordinal}"`):''}</div>`).join('')}</section>`).join('')}${!cap().directory?`<section class="record-note"><h3>Working note</h3><p>${esc(s.profile.summary)}</p></section>`:''}`;}
function input(label,id,value,attrs=''){return `<label class="field"><span>${label}</span><input id="${id}" name="${id}" value="${esc(value)}" ${attrs}></label>`;}
function editForm(focusFamily=null){const s=draft;return `<form id="contact-form"><div class="section-heading"><div><h2>${proposal?'Review the sidekick’s proposal':'Edit contact details'}</h2><p class="muted">${proposal?'The proposal is in your draft. Adjust any field before saving.':'All changes below will be saved together.'}</p></div>${chip('Based on revision '+draft.revision)}</div>${!focusFamily||focusFamily==='profile'?`<div class="profile-fields">${input('Full name','profile-name',s.profile.name,'required maxlength="256" data-path="profile.name"')}${input('Working note','profile-summary',s.profile.summary,'data-path="profile.summary"')}</div>`:''}${families.filter(f=>!focusFamily||focusFamily===f||(focusFamily==='phone'&&f==='address')).map(f=>`<fieldset><legend>${f==='email'?'Email addresses':f==='phone'?'Phone numbers':'Mailing address'}</legend>${s[f].filter(c=>!c.deleted).sort((a,b)=>a.order-b.order).map(c=>`<div class="edit-channel"><div class="channel-edit-heading"><strong>${esc(c.label)||'New '+f}</strong><span>${c.order===1?'Primary':'Position '+c.order}</span>${btn('Make primary','primary','text-button',`data-family="${f}" data-ordinal="${c.ordinal}" ${c.order===1||c.ordinal<0?'disabled':''}`)}</div><div class="form-grid ${f==='address'?'address-grid':''}">${f==='address'?`<label class="field"><span>Mailing address</span><textarea id="address-${c.ordinal}-value" data-path="address.${c.ordinal}.value" rows="3">${esc(c.value)}</textarea></label>`:input(f==='email'?'Email address':'Phone number',`${f}-${c.ordinal}-value`,f==='phone'?c.raw:c.value,`data-path="${f}.${c.ordinal}.${f==='phone'?'raw':'value'}" ${f==='email'?'type="email"':'type="tel"'} required`)}${input('Label',`${f}-${c.ordinal}-label`,c.label,`maxlength="100" data-path="${f}.${c.ordinal}.label"`)}${f==='phone'?input('Extension',`phone-${c.ordinal}-extension`,c.extension,`maxlength="25" data-path="phone.${c.ordinal}.extension"`):''}<label class="field"><span>Directory visibility</span><select id="${f}-${c.ordinal}-public" data-path="${f}.${c.ordinal}.public"><option value="true" ${c.public?'selected':''}>Public</option><option value="false" ${!c.public?'selected':''}>Private</option></select></label></div>${f==='phone'?`<div class="phone-context"><label>Country <select aria-label="Country for phone ${c.ordinal}" data-country="${c.ordinal}"><option value="MX">Mexico (+52)</option></select></label><label>Area code <input aria-label="Area code for phone ${c.ordinal}" id="area-${c.ordinal}" value="${esc(c.area||'777')}" inputmode="numeric" maxlength="3"></label><p id="phone-hint-${c.ordinal}">Interpreted as ${esc(c.value)} · Numbering context only, not residence.</p></div>`:''}${f==='address'?'<p class="help">This correction replaces the address for this contact. Other contacts keep their saved address.</p>':''}</div>`).join('')}${f!=='address'?btn('+ Add '+f,'add','text-button',`data-family="${f}"`):''}</fieldset>`).join('')}<div id="validation" class="validation" role="status"></div></form>`;}
function savebar(){const count=changes().length;return `<div class="savebar"><div><strong id="pending-count">${count} pending field ${count===1?'change':'changes'}</strong><small>One Save · One contact revision${proposal?' · Sidekick proposal':''}</small></div><div>${btn(proposal?'Discard proposal':'Cancel','cancel','quiet')}${btn(busy?'Saving…':'Save changes','save','primary',busy||uncertain||conflict?'disabled':'')}</div></div>`;}
function relayContact(){const labels=['Choose a task','Make the changes','Review & save'];return `${head('YOUR WORK / '+(draft?'IN PROGRESS':'READY'),draft?'A small change, saved together.':'What needs your attention?','A focused path from contact details to a clear record of change.')}<ol class="stepper">${labels.map((x,i)=>`<li class="${step===i?'active':''}">${btn(`<span>${i+1}</span>${x}`,'step','',`data-step="${i}" ${i>0&&!draft?'disabled':''}`)}</li>`).join('')}</ol>${presenceUI()}${step===0?`<div class="relay-start"><section class="relay-person">${recordTitle()}<div class="task-list">${[['email','@','Update an email','Address, label, privacy and saved order'],['phone','⌕','Update a phone or address','Numbering context, extension and mailing details'],['all','↗','Make a combined edit','Name, channels and address in one Save']].map(([f,icon,title,sub])=>btn(`<span class="task-icon">${icon}</span><span><strong>${title}</strong><small>${sub}</small></span><span>→</span>`,'task','task-row',`data-family="${f}" ${!cap().edit?'disabled':''}`)).join('')}</div>${!cap().edit?'<p class="help">This persona can read, but cannot start an editing task.</p>':''}<details class="live-preview"><summary>Read current contact details</summary>${readCard(latest().snapshot)}</details></section><aside class="relay-brief"><p class="eyebrow">BEFORE YOU BEGIN</p><h2>Everyone starts<br>with the same context.</h2><p>Current revision ${latest().revision}. Your draft stays with you until you save.</p><div class="brief-line"><span>01</span>Choose what to change</div><div class="brief-line"><span>02</span>Review it together</div><div class="brief-line"><span>03</span>Follow the evidence</div>${btn('✦ Let the guide stage it','assistant','primary')}</aside></div>`:step===1&&draft?`<div class="relay-edit"><section class="record-paper">${editForm(draft.task==='all'?null:draft.task)}</section><aside class="relay-guide"><p class="eyebrow">AT YOUR SIDE</p><h2>Keep the change small.</h2><p>Update the fields you need. Everything else keeps its saved value.</p>${btn('Stage extension 25 + work primary','assistant-stage','quiet')}<hr>${btn('Continue to review →','review','primary')}${btn('Cancel task','cancel','text-button')}</aside></div>`:draft?`<div class="review-sheet"><p class="eyebrow">READY FOR YOUR DECISION</p><h2>${changes().length} changes. One Save.</h2><p>Based on revision ${draft.revision} · ${esc(draft.profile.name)}</p>${diffTable(changes())}${btn('← Adjust fields','step','quiet','data-step="1"')}${savebar()}</div>`:''}`;}
function diffTable(ds){return ds.length?`<div class="diff-table"><div class="diff-header"><span>Field</span><span>Before</span><span>After</span></div>${ds.map(d=>`<div class="diff-row ${highlight&&d.path.includes(highlight)?'highlight':''}"><strong>${esc(fieldName(d.path))}</strong><div class="before"><small>Before</small>${esc(fmt(d.before)).replace(/\n/g,'<br>')}</div><div class="after"><small>After</small>${esc(fmt(d.after)).replace(/\n/g,'<br>')}</div>`).join('')}</div>`:`<div class="empty-diff"><span>＝</span><div><h3>No final state differences</h3><p>The two snapshots match. Actions during a Save can still tell a different story.</p></div></div>`;}
function historyUI(){if(!cap().history)return `<div class="state-card"><h2>History needs additional access</h2><p>This persona can read public directory details only.</p>${btn('Back to contact','view','primary','data-view="contact"')}</div>`;
  if(simulation==='unavailable')return `<div class="state-card"><h2>Historical coverage is unavailable</h2><p>We cannot reconstruct this revision from the available evidence. Today’s values cannot fill that gap.</p>${btn('Return to available history','normal','primary')}</div>`;
  const r=rev(revision), old=rev(compare), unit=state.units.find(u=>u.id===r.unitId);
  const selector=`<div class="history-selectors"><label>Earlier revision<select id="compare">${revisions().map(x=>`<option value="${x.revision}" ${x.revision===old.revision?'selected':''}>${x.revision} · ${time(x.time)}</option>`).join('')}</select></label><span>→</span><label>Selected revision<select id="revision">${revisions().map(x=>`<option value="${x.revision}" ${x.revision===r.revision?'selected':''}>${x.revision} · ${time(x.time)}</option>`).join('')}</select></label></div>`;
  const modes=`<div class="evidence-tabs" role="group" aria-label="Evidence type">${[['state','State at revision'],['diff','Difference between revisions'],['actions','Actions during Save']].map(([m,t])=>btn(t,'history-mode',historyMode===m?'active':'',`data-mode="${m}" aria-pressed="${historyMode===m}"`)).join('')}</div>`;
  if(variant==='ledger')return `${head('CONTACT HISTORY / THE READING DESK','Read the state. Question the change.','Keep a historical record beside the evidence that explains it.')}<div class="history-top-actions">${contactSwitch()}${btn(backToActivity?'← Back to filtered activity':'← Current contact',backToActivity?'back-activity':'view','quiet','data-view="contact"')}</div><div class="ledger-comparison-bar">${selector}${chip('Historical · read-only','readonly')}</div><div class="ledger-desk"><section class="ledger-snapshot"><p class="eyebrow">THE RECORD / REVISION ${r.revision}</p><div class="historical-state"><h2>${esc(r.snapshot.profile.name)}</h2><p>${esc(r.snapshot.profile.summary)}</p>${snapshotTable(r.snapshot)}</div><p class="help">${esc(r.actor)} · ${time(r.time)} UTC−06<br>Historical values and labels belong to this revision.</p></section><section class="evidence-paper"><p class="eyebrow">THE EXPLANATION</p><div class="evidence-heading"><div><h2>${historyMode==='diff'?`Revision ${old.revision} → ${r.revision}`:historyMode==='actions'?`Inside revision ${r.revision}`:`State at revision ${r.revision}`}</h2><p>${esc(r.title)}<br>${esc(r.actor)} · ${time(r.time)} UTC−06</p></div></div>${modes}${historyMode==='diff'?diffTable(diff(old.snapshot,r.snapshot)):historyMode==='actions'?actionsUI(unit):`<div class="state-reading-note"><span class="folio">${String(r.revision).padStart(2,'0')}</span><h3>This is what remained.</h3><p>The record on the left reconstructs the state at this revision. Its labels, channel positions and mailing address come from the saved snapshot.</p><p>Choose Difference to compare final states, or Actions to see the accepted sequence inside this Save.</p></div>`}<div class="evidence-bottom">${btn('Open audit unit ↗','unit','text-button',`data-unit="${r.unitId}"`)}<span>Selecting history does not undo it.</span></div></section></div><details class="ledger-index"><summary>Browse the revision index · ${revisions().length} saved revisions</summary><div>${revisions().slice().reverse().map(x=>btn(`<span>${String(x.revision).padStart(2,'0')}</span><strong>${esc(x.title)}</strong><small>${time(x.time)} · ${x.actor}</small>`,'revision','',`data-revision="${x.revision}"`)).join('')}</div></details>`;
  const evidence=`<section class="evidence-paper"><div class="evidence-heading"><div><p class="eyebrow">${historyMode==='diff'?'BEFORE & AFTER':historyMode==='state'?'A HISTORICAL SNAPSHOT':'ORDERED BUSINESS EVIDENCE'}</p><h2>${historyMode==='diff'?`Revision ${old.revision} → ${r.revision}`:historyMode==='state'?`State at revision ${r.revision}`:`Inside revision ${r.revision}`}</h2><p>${esc(r.title)} · ${esc(r.actor)} · ${time(r.time)} UTC−06</p></div>${chip('Read-only','readonly')}</div>${selector}${modes}${historyMode==='diff'?diffTable(diff(old.snapshot,r.snapshot)):historyMode==='state'?`<div class="historical-state"><h3>${esc(r.snapshot.profile.name)}</h3><p>${esc(r.snapshot.profile.summary)}</p>${snapshotTable(r.snapshot)}</div>`:actionsUI(unit)}<div class="evidence-bottom">${btn('Open audit unit ↗','unit','text-button',`data-unit="${r.unitId}"`)}<span>Selecting an old revision does not undo it.</span></div></section>`;
  return `${head('CONTACT HISTORY / '+(contact==='lina'?'LINA TORRES':'NORTE TALLER'),variant==='ledger'?'The evidence desk.':variant==='relay'?'Follow the change.':'A clear record of change.','Snapshots tell you what remained. Actions tell you what happened.')}<div class="history-top-actions">${variant==='ledger'?contactSwitch():''}${btn(backToActivity?'← Back to filtered activity':'← Current contact',backToActivity?'back-activity':'view','quiet','data-view="contact"')}</div><div class="history-layout"><aside class="revision-list"><p class="eyebrow">SAVED REVISIONS</p>${revisions().slice().reverse().map(x=>btn(`<span class="revision-number">${String(x.revision).padStart(2,'0')}</span><span><strong>${esc(x.title)}</strong><small>${time(x.time)} · ${x.actor}</small></span>`,'revision','revision-item '+(r.revision===x.revision?'selected':''),`data-revision="${x.revision}"`)).join('')}</aside>${evidence}</div>`;}
function snapshotTable(s){return `<div class="snapshot-table">${families.map(f=>`<h4>${f==='email'?'Email addresses':f==='phone'?'Phone numbers':'Mailing address'}</h4>${s[f].slice().sort((a,b)=>a.order-b.order).map(c=>`<div class="snapshot-row"><span>${esc(c.label)} ${c.deleted?chip('Deleted'):chip(c.order===1?'Primary':'Position '+c.order)}</span><strong>${esc(c.value).replace(/\n/g,'<br>')}${c.extension?`<br><small>Extension ${esc(c.extension)}</small>`:''}</strong><span>${c.public?'Public':'Private'}</span></div>`).join('')}`).join('')}</div>`;}
function actionsUI(u){return `<ol class="action-list">${u.actions.map(a=>`<li><span class="action-number">${a.order}</span><div><h3>${esc(a.kind.replace('.',' · '))}</h3>${a.changes.map(d=>`<p class="action-change"><strong>${esc(fieldName(d.path))}</strong><span>Before: ${esc(fmt(d.before))}</span><span>After: ${esc(fmt(d.after))}</span></p>`).join('')}</div></li>`).join('')}</ol>`;}
function activityUI(){if(!cap().activity)return `<div class="state-card"><h2>Activity requires an audit grant</h2><p>Public directory access does not include private history or actions.</p>${btn('Back to contact','view','primary','data-view="contact"')}</div>`;
  const units=simulation==='empty'?[]:filteredUnits();
  const selected=state.units.find(x=>x.id===selectedUnit);
  const field=(id,label,options)=>`<label><span>${label}</span><select id="filter-${id}"><option value="">All ${label.toLowerCase()}s</option>${options.map(([v,n])=>`<option value="${v}" ${filters[id]===v?'selected':''}>${n}</option>`).join('')}</select></label>`;
  const rows=units.map(u=>btn(`<span class="activity-date">${time(u.time)}<small>UTC−06</small></span><span class="activity-summary"><strong>${esc(u.title)}</strong><small>${u.contact==='lina'?'Lina Torres':'Norte Taller'} · Revision ${u.revision}</small></span><span class="actor-cell"><span class="avatar small">${u.actor[0]}</span>${u.actor}</span><span class="family-cell">${[...new Set(u.actions.map(a=>a.kind.split('.')[0]))].map(f=>chip(f)).join('')}</span><span>↗</span>`,'unit','activity-row '+(selectedUnit===u.id?'selected':''),`data-unit="${u.id}"`)).join('');
  return `${head('VÉRTICE DEMO / APPLICATION ACTIVITY',variant==='ledger'?'A record, across the workspace.':variant==='relay'?'The work, saved.':'Tenant activity.','Committed business changes, grouped by the Save that made them.')}<div class="activity-intro">${chip(cap().admin?'Administrator view':cap().edit?'Authorized contact scope':'Read-only audit access','soft')}<span>Ordered by recorded time · ${units.length} matching Saves</span></div><section class="filter-bar"><label class="search-field"><span>Search activity</span><input type="search" id="filter-search" placeholder="Name, change or actor…" value="${esc(filters.search)}"></label>${field('actor','Actor',Object.keys(personas).filter(n=>personas[n].edit).map(n=>[n,n]))}${field('contact','Contact',[['lina','Lina Torres'],['norte','Norte Taller']])}${field('family','Family',[['profile','Profile'],['email','Email'],['phone','Phone'],['address','Address']])}<label><span>Time range</span><select id="filter-range"><option value="all">All recorded time</option><option value="week" ${filters.range==='week'?'selected':''}>Story week · Sep 1–8</option><option value="recent" ${filters.range==='recent'?'selected':''}>Sep 7 onward</option></select></label>${btn('Clear','clear-filters','text-button')}</section><div class="activity-layout ${selected?'has-unit':''}"><section class="activity-list"><div class="activity-list-head"><span>RECORDED AT</span><span>SAVED TOGETHER</span><span>CHANGED BY</span><span>FAMILIES</span></div>${rows||`<div class="state-card"><span class="big-glyph">⌕</span><h2>No matching changes</h2><p>Try a wider time range or clear a filter.</p>${btn('Clear filters','clear-filters','primary')}</div>`}<p class="activity-footnote">Presence and local demo errors are separate from this committed business history.</p></section>${selected?unitUI(selected):''}</div>`;}
function unitUI(u){return `<aside class="unit-detail" aria-label="Audit unit detail"><div class="section-heading"><p class="eyebrow">AUDIT UNIT</p>${btn('×','close-unit','icon-button','aria-label="Close audit unit"')}</div><h2>${esc(u.title)}</h2><p>Changed by <strong>${u.actor}</strong><br>${time(u.time)} · UTC−06</p>${chip('Saved together','primary-chip')}<h3>Affected record</h3>${btn(`${u.contact==='lina'?'Lina Torres':'Norte Taller'}<br><small>Revision ${u.revision} · Open difference →</small>`,'unit-contact','unit-contact',`data-contact="${u.contact}" data-revision="${u.revision}"`)}<h3>Actions in order</h3>${actionsUI(u)}<details class="technical"><summary>Technical details</summary><dl><dt>Correlation</dt><dd>${u.id}</dd><dt>Audit stamp (Int64 string)</dt><dd>${u.stamp}</dd><dt>Source</dt><dd>${u.source}</dd></dl><p>Allocation stamps do not prove cross-contact commit order or a universal snapshot.</p></details></aside>`;}
function conflictUI(){const incoming=diff(base,conflict.snapshot),mine=changes();const overlaps=mine.filter(d=>incoming.some(x=>x.path===d.path&&JSON.stringify(x.after)!==JSON.stringify(d.after)));return `<section class="conflict" role="alert"><p class="eyebrow">YOUR DRAFT IS SAFE</p><h2>Another Save arrived first.</h2><p>${conflict.actor} saved revision ${conflict.revision}. You started at revision ${draft.revision}. Review the latest changes and choose how to resolve any overlap.</p><div class="conflict-columns"><div><h3>Your pending changes</h3>${mine.map(d=>`<p><strong>${esc(fieldName(d.path))}</strong><br>${esc(fmt(d.before))} → ${esc(fmt(d.after))}</p>`).join('')}</div><div><h3>Latest saved changes</h3>${incoming.map(d=>`<p><strong>${esc(fieldName(d.path))}</strong><br>${esc(fmt(d.before))} → ${esc(fmt(d.after))}</p>`).join('')}</div></div>${overlaps.map(d=>`<fieldset class="resolve-field"><legend>${esc(fieldName(d.path))}</legend><label><input type="radio" name="resolve-${d.path}" data-choice="${d.path}" value="mine" ${choices[d.path]==='mine'?'checked':''}> Keep mine: ${esc(fmt(d.after))}</label><label><input type="radio" name="resolve-${d.path}" data-choice="${d.path}" value="latest" ${choices[d.path]==='latest'?'checked':''}> Keep latest: ${esc(fmt(incoming.find(x=>x.path===d.path).after))}</label></fieldset>`).join('')}<p>${overlaps.length?'Choose once for each overlapping field.':'The fields do not overlap. Reconciliation can preserve both sets of changes.'}</p>${btn('Reconcile draft with latest','reconcile','primary')}${btn('Discard my draft','cancel','quiet')}</section>`;}
function assistantUI(){const context=`${contact==='lina'?'Lina Torres':'Norte Taller'} · ${view==='history'?'revision '+rev(revision).revision:view} · ${persona} · ${changes().length} pending fields`;return `<aside class="sidekick ${variant==='relay'?'guide-sheet':''}" role="dialog" aria-modal="false" aria-label="Contextual sidekick"><header><div><span class="assistant-star">✦</span><strong>${variant==='relay'?'Your task guide':variant==='ledger'?'Evidence companion':'Sidekick'}</strong></div>${btn('×','close-assistant','icon-button','aria-label="Close sidekick"')}</header><div class="sidekick-scroll"><p class="eyebrow">WORKING WITH THIS VIEW</p><div class="assistant-context">${esc(context)}${view==='activity'?`<br>Filters: ${esc(Object.entries(filters).filter(([,v])=>v).map(([k,v])=>`${k}: ${v}`).join(' · '))}`:''}</div><h2>${variant==='relay'?'Let’s move this forward.':'Less searching.<br>More understanding.'}</h2><p>Read the evidence, find a change, or prepare an edit for your review.</p><div class="suggestions">${btn('What changed in Lina’s contact this week?','assistant-week')}${btn('Show Bruno’s phone changes.','assistant-bruno')}${btn('Change this extension to 25 and make the work email primary.','assistant-stage')}</div><div class="assistant-answer" aria-live="polite">${assistantMessage||'<p class="muted">Answers use local contact revisions and your current permissions.</p>'}</div><label class="field"><span>Ask about this view</span><textarea id="assistant-question" rows="2" placeholder="Ask a question or describe an edit…"></textarea></label>${btn('Ask sidekick','assistant-ask','primary')}<details class="assistant-source"><summary>What the sidekick is using</summary><p>Simulated local rules; no external AI calls. Authorized record snapshots, selected evidence, active filters and this tab’s unsaved draft. Responses are recomputed after changes.</p></details></div></aside>`;}
function summaryAnswer(){
  if(!cap().history)return '<p>Your directory grant does not include history. I can show public current channels only.</p>';
  const all=state.contacts.lina.revisions, rs=all.filter(r=>r.time>='2026-09-01'&&r.time<'2026-09-09');
  const unchanged=rs.filter(r=>{const prev=all.find(x=>x.revision===r.revision-1);return prev&&diff(prev.snapshot,r.snapshot).length===0;});
  return `<h3>Lina’s story week · Sep 1–8</h3><p>${rs.length} saved revisions in America/Mexico_City.</p>${rs.map(r=>btn(`<strong>Revision ${r.revision}</strong> · ${esc(r.title)}<small>${r.actor} · ${time(r.time)}</small>`,'assistant-ref','citation',`data-revision="${r.revision}"`)).join('')}${unchanged.map(r=>`<p>Revision ${r.revision} retains ${state.units.find(u=>u.id===r.unitId).actions.length} actions with no final state difference.</p>`).join('')}${draft?`<p>Your ${changes().length} pending field changes are not included in saved history.</p>`:''}`;
}
let assistantIntent='';
function refreshAnswer(){if(assistantIntent==='week')assistantMessage=summaryAnswer();if(assistantIntent==='stage')assistantMessage=proposal&&draft?`<h3>Proposal ready for review</h3><p>${changes().length} pending field changes in your normal contact form. Proposed primary phone extension: ${esc(draft.phone.filter(x=>!x.deleted).sort((a,b)=>a.order-b.order)[0]?.extension||'none')}. Proposed primary email: ${esc(draft.email.filter(x=>!x.deleted).sort((a,b)=>a.order-b.order)[0]?.label||'none')}. Nothing has been saved by this proposal.</p>${btn('Review draft →','review-proposal','primary')}${btn('Discard proposal','cancel','quiet')}`:'<p>There is no active proposal. The current view reflects the latest local state.</p>';if(assistantIntent==='bruno')assistantMessage=cap().activity?`<h3>Bruno’s phone evidence</h3><p>The activity query now uses ${esc(filters.actor||'all actors')} and ${esc(filters.family||'all families')}. ${filteredUnits().length} Saves match the current filters.</p>`:'<p>Your current grant does not include action evidence.</p>';}
function syncAssistant(){if(!sidekick)return;refreshAnswer();const context=$('.assistant-context'),answer=$('.assistant-answer');if(context)context.textContent=`${contact==='lina'?'Lina Torres':'Norte Taller'} · ${view} · ${persona} · ${changes().length} pending fields`;if(answer){answer.innerHTML=assistantMessage;answer.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>act(el.dataset.action,el)));}}
function renderPassive(){if(draft){const p=$('.presence');if(p)p.outerHTML=presenceUI();syncAssistant();}else render();}
function bind(){
  $$('[data-action]').forEach(el=>el.addEventListener('click',()=>act(el.dataset.action,el)));
  $('#persona')?.addEventListener('change',async e=>{persona=e.target.value;sessionStorage.setItem('overmind-a-persona-'+variant,persona);clearDraft();assistantIntent='';assistantMessage='';notice='';selectedUnit=null;$('#app').innerHTML='<main class="state-card" aria-busy="true"><h2>Loading this persona’s permitted view…</h2></main>';await refresh(false);await presence();render();});
  $('#simulation')?.addEventListener('change',e=>{simulation=e.target.value;if(simulation==='empty')view='activity';if(simulation==='unavailable')view='history';render();});
  $$('[data-path]').forEach(el=>el.addEventListener(el.tagName==='SELECT'?'change':'input',()=>{
    let value=el.tagName==='SELECT'?el.value==='true':el.value;setPath(draft,el.dataset.path,value);
    if(el.dataset.path.endsWith('.raw'))updatePhone(el);
    const count=changes().length;if($('#pending-count'))$('#pending-count').textContent=`${count} pending field changes`;
    $('#validation').textContent='';
    syncAssistant();
  }));
  $$('[id^="area-"]').forEach(el=>el.addEventListener('input',()=>{const n=el.id.split('-')[1];updatePhone($('#phone-'+n+'-value'));}));
  $('#contact-form')?.addEventListener('submit',e=>{e.preventDefault();act('save');});
  $('#revision')?.addEventListener('change',e=>{revision=Number(e.target.value);refreshAnswer();render();});
  $('#compare')?.addEventListener('change',e=>{compare=Number(e.target.value);render();});
  for(const f of Object.keys(filters))$('#filter-'+f)?.addEventListener(f==='search'?'input':'change',e=>{filters[f]=e.target.value;selectedUnit=null;refreshAnswer();render();});
  $$('[data-choice]').forEach(el=>el.addEventListener('change',()=>{choices[el.dataset.choice]=el.value;}));
}
function updatePhone(el){const id=Number(el.dataset.path.split('.')[1]), c=draft.phone.find(x=>x.ordinal===id);try{const p=parsePhone(el.value,'MX',$('#area-'+id)?.value||'777');c.value=p.number;c.region='MX';c.area=$('#area-'+id)?.value||'777';$('#phone-hint-'+id).textContent=`Interpreted as ${p.number} · Numbering context only, not residence.`;el.setCustomValidity('');}catch(e){$('#phone-hint-'+id).textContent=e.message;el.setCustomValidity(e.message);}}
async function doSave(){if(!draft||uncertain||conflict||busy)return;try{validate(draft);if($('#contact-form')&&!$('#contact-form').reportValidity())return;}catch(e){error=e.message;render();return;}
  if(!changes().length){error='There are no pending changes. Edit a field or cancel the draft.';render();return;}
  busy=true;render();let result;try{result=await api('save',{id:contact,expectedEntityVersion:draft.revision,epoch:draftEpoch,commands:commandsFrom(base,draft),uncertain:simulation==='uncertain'});}catch{result={code:'commit_uncertain'};}busy=false;
  if(result.code==='conflict'){conflict=result.latest;choices={};error='';await refresh(false);}
  else if(result.code==='commit_uncertain'){uncertain=true;simulation='';error='';await refresh(false);}
  else if(result.httpStatus!==200){error=result.message||'This Save is not permitted.';}
  else{clearDraft();await refresh(false);revision=result.revision;notice=`Saved together · Revision ${result.revision} · Changed by ${persona}`;step=0;}
  refreshAnswer();render();await presence();
}
async function act(action,el={dataset:{}}){
  const d=el.dataset;
  if(action==='theme'){theme=theme==='light'?'dark':'light';localStorage.setItem('overmind-a-theme-'+variant,theme);document.documentElement.dataset.theme=theme;}
  if(action==='demo')demo=!demo;
  if(action==='normal')simulation='';
  if(action==='dismiss-notice')notice='';
  if(action==='view'){view=d.view;if(view==='history'){revision=latest().revision;compare=Math.max(1,revision-1);}simulation='';}
  if(action==='contact') {if(draft){error='Save or cancel this draft before switching contacts.';}else{contact=d.contact;view='contact';step=0;notice='';}}
  if(action==='edit'){if(startDraft()){view='contact';step=1;draft.task='all';}render();if(d.field)$('#'+d.field)?.focus();else $('#profile-name')?.focus();await presence();return;}
  if(action==='task'){if(startDraft()){draft.task=d.family;step=1;}render();$('#contact-form input')?.focus();await presence();return;}
  if(action==='step'){step=Number(d.step);}
  if(action==='review'){try{validate(draft);if($('#contact-form')&&!$('#contact-form').reportValidity())return;step=2;error='';}catch(e){error=e.message;}}
  if(action==='primary'){const f=d.family, id=Number(d.ordinal),live=draft[f].filter(x=>!x.deleted).sort((a,b)=>a.order-b.order);const c=live.find(x=>x.ordinal===id);live.splice(live.indexOf(c),1);live.unshift(c);live.forEach((x,i)=>x.order=i+1);}
  if(action==='add'){if(startDraft()){const f=d.family;if(f!=='address'){const id=Math.min(0,...draft[f].map(x=>x.ordinal))-1;draft[f].push({ordinal:id,value:'',raw:'',label:f==='email'?'Other':'Work',order:draft[f].filter(x=>!x.deleted).length+1,public:false,deleted:false,...(f==='phone'?{extension:''}:{})});step=1;draft.task='all';render();$('#'+f+'-'+id+'-value')?.focus();return;}}}
  if(action==='cancel'){const wasUncertain=uncertain;if(proposal&&proposalBackup){draft=proposalBackup;proposalBackup=null;proposal=false;notice='Proposal discarded. Your earlier unsaved draft is restored.';}else{clearDraft();step=0;notice=wasUncertain?'Local draft discarded. Review the latest saved state to investigate the unknown response.':'Local draft discarded. No changes were saved by cancelling.';}}
  if(action==='save'){await doSave();return;}
  if(action==='saved-history')openHistory(revision<=latest().revision?revision:latest().revision);
  if(action==='revision'){openHistory(d.revision,backToActivity);}
  if(action==='history-mode')historyMode=d.mode;
  if(action==='unit'){selectedUnit=d.unit;view='activity';}
  if(action==='close-unit')selectedUnit=null;
  if(action==='unit-contact'){if(draft&&contact!==d.contact){error='Save or cancel the draft before opening another contact.';}else{contact=d.contact;openHistory(d.revision,true);}}
  if(action==='back-activity')view='activity';
  if(action==='clear-filters'){filters={search:'',actor:'',contact:'',family:'',range:'all'};simulation='';selectedUnit=null;}
  if(action==='assistant'){sidekick=!sidekick;focusReturn='assistant';render();if(sidekick)$('#assistant-question')?.focus();else $('#assistant')?.focus();return;}
  if(action==='close-assistant'){sidekick=false;render();$('#'+focusReturn)?.focus();return;}
  if(action==='assistant-week'){sidekick=true;assistantIntent='week';}
  if(action==='assistant-bruno'){sidekick=true;assistantIntent='bruno';if(cap().activity){view='activity';filters={search:'',actor:'Bruno',contact:'',family:'phone',range:'all'};selectedUnit=null;}}
  if(action==='assistant-ref'){if(draft&&contact!=='lina'){error='Finish this draft before opening Lina’s history.';}else{contact='lina';openHistory(d.revision);highlight='phone';sidekick=false;}}
  if(action==='assistant-stage'){
    sidekick=true;assistantIntent='';
    if(!cap().edit){assistantMessage='<p>You have read access. I cannot stage writes for this persona.</p>';}
    else if(uncertain||conflict){assistantMessage='<p>Resolve the outstanding Save outcome before staging another proposal.</p>';}
    else {if(!proposal)proposalBackup=draft?clone(draft):null;if(startDraft()){
      const phone=draft.phone.filter(x=>!x.deleted).sort((a,b)=>a.order-b.order)[0];if(phone)phone.extension='25';
      const work=draft.email.find(x=>!x.deleted&&x.label.toLowerCase()==='work');if(work){const list=draft.email.filter(x=>!x.deleted).sort((a,b)=>a.order-b.order);list.splice(list.indexOf(work),1);list.unshift(work);list.forEach((x,i)=>x.order=i+1);}
      proposal=true;assistantIntent='stage';view='contact';step=1;draft.task='all';
    }}
  }
  if(action==='review-proposal'){view='contact';step=variant==='relay'?2:1;sidekick=false;}
  if(action==='assistant-ask'){const q=$('#assistant-question').value.toLowerCase();if(q.includes('bruno')&&q.includes('phone'))return act('assistant-bruno');if(q.includes('week')&&q.includes('lina'))return act('assistant-week');if(q.includes('25')&&q.includes('primary'))return act('assistant-stage');assistantIntent='';assistantMessage='<p>I can summarize Lina’s story week, find Bruno’s phone changes, or stage extension 25 and work email primary. I do not have evidence or tools for that other request.</p>';}
  if(action==='reset'||action==='scenario'){transitioning=true;$('#app').innerHTML='<main class="state-card" aria-busy="true"><h2>Restoring the local demo story…</h2></main>';await api('reset',{atThree:action==='scenario'});clearDraft();notice='';filters={search:'',actor:'',contact:'',family:'',range:'all'};selectedUnit=null;simulation='';assistantIntent='';assistantMessage='';contact='lina';view='contact';step=0;await refresh(false);revision=latest().revision;compare=Math.max(1,revision-1);if(action==='scenario'){startDraft();draft.phone[0].extension='25';draft.task='all';step=1;notice='The draft starts at revision 3. Save Bruno’s update from another tab or the demo control.';}transitioning=false;}
  if(action==='bruno'){await api('bruno',{});await refresh(false);notice='Bruno saved an office phone update. Existing drafts still use their original revision.';}
  if(action==='reconcile'){
    const incoming=diff(base,conflict.snapshot),mine=changes(),overlaps=mine.filter(d=>incoming.some(x=>x.path===d.path&&JSON.stringify(x.after)!==JSON.stringify(d.after)));
    if(overlaps.some(d=>!choices[d.path])){error='Choose Keep mine or Keep latest for every overlapping field.';render();return;}
    const reconciled=clone(conflict.snapshot);
    for(const f of families) for(const c of draft[f].filter(x=>x.ordinal<0)) reconciled[f].push(clone(c));
    for(const change of mine)if(choices[change.path]!=='latest')setPath(reconciled,change.path,change.after);
    base=clone(conflict.snapshot);reconciled.revision=conflict.revision;reconciled.task='all';draft=reconciled;draftEpoch=state.epoch;conflict=null;choices={};error='';notice='Draft reconciled with latest. Review it, then Save explicitly.';view='contact';step=1;
  }
  if(action==='investigate'){await refresh(false);openHistory(latest().revision);notice='Latest state loaded. Compare your preserved draft with the saved revision; the original response remains unknown.';}
  refreshAnswer();render();await presence();
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sidekick){e.preventDefault();act('close-assistant');}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();if(variant==='relay'&&step===1)act('review');else act('save');}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();act('assistant');}});
function gallery(){document.body.dataset.variant='gallery';$('#app').innerHTML=`<main id="main" class="gallery"><header>${identity()}<span>DESIGN EXPLORATIONS / AGENT A</span></header><p class="eyebrow">OPERATIONAL CLARITY</p><h1>Small edits.<br>Clear consequences.</h1><p class="gallery-lede">Three ways to move from a contact detail to the evidence behind it.<br>One shared story. Three distinct ways of working.</p><div class="concept-grid">${Object.entries(concepts).map(([id,c])=>`<a class="concept ${id}" href="/${id}"><div class="concept-preview"><span>${c.number}</span>${id==='dispatch'?'<div class="mini-rail"></div><div class="mini-lines"><i></i><i></i><i></i></div>':id==='ledger'?'<div class="mini-folio">Aa</div><div class="mini-lines"><i></i><i></i></div>':'<div class="mini-steps"><b>1</b><b>2</b><b>3</b></div><div class="mini-lines"><i></i><i></i></div>'}</div><div class="concept-copy"><span class="eyebrow">${c.tag}</span><h2>${c.name} <span>↗</span></h2><p>${c.thesis}</p><span class="open-concept">Open working prototype →</span></div></a>`).join('')}</div><footer>Vértice Demo · Fictional data · Local simulation · Light & dark · Two-tab collaboration</footer></main>`;}
if(!concepts[variant])gallery();else{
  await refresh(false);revision=latest().revision;compare=Math.max(1,revision-1);render();await presence();
  const events=new EventSource(endpoint('events')+'&tab='+encodeURIComponent(tabId));
  events.onmessage=async()=>{if(transitioning)return;const oldEpoch=state.epoch;await refresh(false);if(transitioning)return;if(oldEpoch!==state.epoch&&draft){clearDraft();notice='The demo story was reset in another tab. The old draft was cleared to avoid mixing stories.';}refreshAnswer();renderPassive();};
  setInterval(async()=>{await presence();const old=JSON.stringify(peers);await refresh(false);if(old!==JSON.stringify(peers)){refreshAnswer();renderPassive();}},10000);
}
